<template><section class="builder-panel game-panel"><header class="builder-panel__heading"><strong>Game Preview</strong><small>Draft game preview</small></header><div class="game-picker"><label>Game<select :value="current.id" @change="select($event.target.value)"><option v-for="item in choices" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><strong>{{ current.context }}</strong><span>{{ current.brightness }} brightness · {{ current.motion }} motion</span><small>{{ current.contrast }}</small></div><div class="preview-choices"><button v-for="item in choices" :key="item.id" :class="{active:item.id===current.id}" @click="select(item.id)"><span :style="{backgroundImage:`url(${item.image})`}"></span><b>{{ item.name }}</b><small>{{ item.brightness }} · {{ item.motion }} motion</small></button></div><label class="custom-background">Custom background concept<input type="file" accept="image/*" @change="$emit('upload',$event)"></label><p>Draft game preview · Preview only · Not included in output</p></section></template>
<script setup>import{computed}from'vue';import{applyGamePreview,gamePreviewDefinitions as choices,resolveGamePreview}from'../../overlays/gamePreviewDefinitions.js';const props=defineProps({preview:Object});const emit=defineEmits(['change','upload']);const current=computed(()=>resolveGamePreview(props.preview.gameId||props.preview.referenceAssetId));function select(id){emit('change',applyGamePreview(props.preview,id))}</script>
